// Find existing lead record by phone number
const phone = $('Normalize Message Fields').item.json.phoneNumber;
const sheetData = $input.item.json;

let existingLead = null;
let conversationStage = 'new';
let bantScore = { budget: false, authority: false, need: false, timeline: false };
let conversationHistory = [];
let leadScore = 0;

if (sheetData.values && sheetData.values.length > 1) {
  const rows = sheetData.values.slice(1); // skip header
  const found = rows.find(row => row[1] === phone);
  if (found) {
    existingLead = {
      id: found[0],
      phone: found[1],
      name: found[2],
      stage: found[3] || 'new',
      leadScore: parseInt(found[4]) || 0,
      bantBudget: found[5] === 'TRUE',
      bantAuthority: found[6] === 'TRUE',
      bantNeed: found[7] === 'TRUE',
      bantTimeline: found[8] === 'TRUE',
      conversationHistory: found[9] ? JSON.parse(found[9]) : []
    };
    conversationStage = existingLead.stage;
    bantScore = {
      budget: existingLead.bantBudget,
      authority: existingLead.bantAuthority,
      need: existingLead.bantNeed,
      timeline: existingLead.bantTimeline
    };
    conversationHistory = existingLead.conversationHistory;
    leadScore = existingLead.leadScore;
  }
}

const message = $('Normalize Message Fields').item.json.incomingMessage;

// Add incoming message to history
conversationHistory.push({
  role: 'user',
  content: message,
  ts: new Date().toISOString()
});

// Cap history at last 20 messages to stay within token limits
if (conversationHistory.length > 20) {
  conversationHistory = conversationHistory.slice(-20);
}

return {
  json: {
    ...$('Normalize Message Fields').item.json,
    isNewLead: !existingLead,
    conversationStage,
    bantScore,
    leadScore,
    conversationHistory,
    existingLead
  }
};

const item = $input.item.json;
const aiResponse = item.output || item.response || item.text || 'Thank you for reaching out! How can I help you today?';

// Update BANT score based on AI output hints
const bantScore = item.bantScore || { budget: false, authority: false, need: false, timeline: false };
const responseLower = aiResponse.toLowerCase();

// Simple keyword-based BANT detection (AI handles the nuanced conversation)
if (responseLower.includes('[budget_confirmed]')) bantScore.budget = true;
if (responseLower.includes('[authority_confirmed]')) bantScore.authority = true;
if (responseLower.includes('[need_confirmed]')) bantScore.need = true;
if (responseLower.includes('[timeline_confirmed]')) bantScore.timeline = true;

// Calculate lead score (25 points per BANT element)
const newLeadScore = Object.values(bantScore).filter(Boolean).length * 25;

// Determine conversation stage
let stage = item.conversationStage || 'new';
if (newLeadScore === 0) stage = 'awareness';
else if (newLeadScore <= 25) stage = 'qualifying';
else if (newLeadScore <= 75) stage = 'engaged';
else stage = 'hot_lead';

// Add AI reply to history
const updatedHistory = [...(item.conversationHistory || []), {
  role: 'assistant',
  content: aiResponse,
  ts: new Date().toISOString()
}];

// Clean reply text (remove internal tags)
const cleanReply = aiResponse
  .replace(/\[budget_confirmed\]/gi, '')
  .replace(/\[authority_confirmed\]/gi, '')
  .replace(/\[need_confirmed\]/gi, '')
  .replace(/\[timeline_confirmed\]/gi, '')
  .trim();

return {
  json: {
    ...item,
    replyText: cleanReply,
    bantScore,
    leadScore: newLeadScore,
    conversationStage: stage,
    conversationHistory: updatedHistory,
    updatedAt: new Date().toISOString().split('T')[0]
  }
};

